from math import gcd
from sympy import primerange, factorint

def solve():
    n = 2100
    k = 2026  # We want the 2026th smallest

    # Generate all primes up to n
    primes = list(primerange(1, n + 1))

    # For each prime, collect all exponents from numbers 1 to n
    prime_exponents = {}
    for i in range(1, n + 1):
        factors = factorint(i)
        for p in primes:
            exp = factors.get(p, 0)
            if p not in prime_exponents:
                prime_exponents[p] = []
            prime_exponents[p].append(exp)

    # Sort the exponents for each prime
    for p in primes:
        if p in prime_exponents:
            prime_exponents[p].sort()

    # Get the k-th exponent for each prime (k-th smallest, 1-indexed)
    k_th_exponents = {}
    for p in primes:
        if p in prime_exponents:
            # Adjust for 0-indexing
            if len(prime_exponents[p]) >= k:
                k_th_exponents[p] = prime_exponents[p][k - 1]
            else:
                k_th_exponents[p] = prime_exponents[p][-1]  # Take max if k > n (shouldn't happen)

    # Compute the target number
    target_number = 1
    for p, exp in k_th_exponents.items():
        target_number *= (p ** exp)

    print(f"Target number: {target_number}")

    # Count divisors by factorizing again
    factors = factorint(target_number)
    divisor_count = 1
    for exp in factors.values():
        divisor_count *= (exp + 1)

    print(f"Divisor count: {divisor_count}")
    return divisor_count

result = solve()
print(f"\nFinal answer: {result}")

